SELECT s1.`c0` AS `x` FROM (SELECT s2.`c7` AS `c0` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c2` AS `c2`, s3.`c3` AS `c3`, s3.`c4` AS `c4`, s3.`c5` AS `c5`, s3.`c6` AS `c6`, s3.`c3` AS `c7` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c2` AS `c2`, s4.`c3` AS `c3`, s4.`c4` AS `c4`, s4.`c5` AS `c5`, s4.`c6` AS `c6` FROM (SELECT `d` AS `c0`, `d2` AS `c1`, `ts` AS `c2`, `x` AS `c3`, `s` AS `c4`, `ok` AS `c5`, `v` AS `c6` FROM `events`) AS s4 WHERE (((CASE WHEN s4.`c6` IS NULL THEN NULL WHEN isnan(s4.`c6`) THEN 1 ELSE 0 END) < (CASE WHEN CAST(CAST(s4.`c3` AS BIGINT) AS DOUBLE) IS NULL THEN NULL WHEN isnan(CAST(CAST(s4.`c3` AS BIGINT) AS DOUBLE)) THEN 1 ELSE 0 END) OR ((CASE WHEN s4.`c6` IS NULL THEN NULL WHEN isnan(s4.`c6`) THEN 1 ELSE 0 END) = 0 AND (CASE WHEN CAST(CAST(s4.`c3` AS BIGINT) AS DOUBLE) IS NULL THEN NULL WHEN isnan(CAST(CAST(s4.`c3` AS BIGINT) AS DOUBLE)) THEN 1 ELSE 0 END) = 0 AND (s4.`c6` < CAST(CAST(s4.`c3` AS BIGINT) AS DOUBLE) OR (s4.`c6` = CAST(CAST(s4.`c3` AS BIGINT) AS DOUBLE) AND (CAST(s4.`c6` AS STRING) LIKE '-%') AND NOT (CAST(CAST(CAST(s4.`c3` AS BIGINT) AS DOUBLE) AS STRING) LIKE '-%'))))) IS TRUE)) AS s3) AS s2) AS s1
